// cap-nhat.mjs: tệp TỰ CẬP NHẬT cho "Công ty AI".
//
// Cách dùng: đặt tệp này vào thư mục dự án (cùng chỗ với server.js), rồi chạy cap-nhat.bat (hoặc: node cap-nhat.mjs).
// Nó so từng tệp mã nguồn với bản đúng, sao lưu tệp cũ vào thư mục sao-luu-..., rồi chép đúng chỗ những tệp sai hoặc thiếu.
// Nó KHÔNG đụng tới config.json, thư mục data/ (dữ liệu của bạn) và start.bat.
// Tuỳ chọn: --chi-kiem-tra (chỉ xem, không sửa)   --json (in kết quả dạng JSON)   --goc <thư mục> (chỉ định thư mục dự án)
import { readFileSync, writeFileSync, mkdirSync, existsSync, copyFileSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const MA_BAN = '96373d7a';
const FILES = {
  "package.json": "",
  "public/css/app.css": "",
  "public/img/logo.svg": "",
  "public/index.html": "",
  "public/js/api.js": "",
  "public/js/app.js": "",
  "public/js/boot-guard.js": "",
  "public/js/gl/audio.js": "",
  "public/js/gl/behavior.js": "",
  "public/js/gl/building.js": "",
  "public/js/gl/engine.js": "",
  "public/js/gl/flow.js": "",
  "public/js/gl/hotkeys.js": "",
  "public/js/gl/labels.js": "",
  "public/js/gl/math.js": "",
  "public/js/gl/people.js": "",
  "public/js/gl/screens.js": "",
  "public/js/gl/shapes.js": "",
  "public/js/gl/sky.js": "",
  "public/js/gl/textures.js": "",
  "public/js/gl/weather.js": "",
  "public/js/gl/world.js": "",
  "public/js/guide-data.js": "",
  "public/js/heat.js": "",
  "public/js/kiosk-logic.js": "",
  "public/js/kiosk.js": "",
  "public/js/map2d.js": "",
  "public/js/office3d.js": "",
  "public/js/office_gl.js": "",
  "public/js/pages.js": "",
  "public/js/pages10.js": "",
  "public/js/pages5.js": "",
  "public/js/pages8.js": "",
  "public/js/pages9.js": "",
  "public/js/shell9.js": "",
  "public/js/ui.js": "",
  "server.js": "",
  "src/ai/anthropic.js": "",
  "src/ai/checks.js": "",
  "src/ai/config.js": "",
  "src/ai/errors.js": "",
  "src/ai/files.js": "",
  "src/ai/gemini.js": "",
  "src/ai/http.js": "",
  "src/ai/limiter.js": "",
  "src/ai/openai.js": "",
  "src/ai/prompts.js": "",
  "src/ai/providers.js": "",
  "src/ai/secrets.js": "",
  "src/ai/service.js": "",
  "src/api.js": "",
  "src/app.js": "",
  "src/approvals.js": "",
  "src/assistant.js": "",
  "src/backup.js": "",
  "src/bugs.js": "",
  "src/checkfront.js": "",
  "src/costs.js": "",
  "src/db.js": "",
  "src/events.js": "",
  "src/heatmap.js": "",
  "src/knowledge.js": "",
  "src/notify.js": "",
  "src/planner.js": "",
  "src/pricing.js": "",
  "src/projects.js": "",
  "src/reports.js": "",
  "src/seed.js": "",
  "src/settings.js": "",
  "src/sim.js": "",
  "src/text.js": "",
  "src/work.js": "",
};

const args = process.argv.slice(2);
const has = n => args.includes(n), val = n => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : null; };
const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(val('--goc') || here);
const onlyCheck = has('--chi-kiem-tra'), asJson = has('--json');
const say = (...a) => { if (!asJson) console.log(...a); };

// So sánh bỏ qua khác biệt xuống dòng (Windows/Linux) và dấu BOM đầu tệp.
const norm = b => Buffer.from(b.toString('latin1').replace(/^\xef\xbb\xbf/, '').replace(/\r\n/g, '\n'), 'latin1');
const sha = b => crypto.createHash('sha256').update(norm(b)).digest('hex');
const expected = new Map(Object.entries(FILES).map(([rel, b64]) => [rel, Buffer.from(b64, 'base64')]));
const expSha = new Map([...expected].map(([rel, b]) => [rel, sha(b)]));
const byHash = new Map([...expSha].map(([rel, h]) => [h, rel]));
const safe = rel => { const t = path.resolve(root, rel); if (t !== root && !t.startsWith(root + path.sep)) throw new Error('Đường dẫn không an toàn: ' + rel); return t; };
const walk = dir => readdirSync(dir).flatMap(n => { const f = path.join(dir, n); return statSync(f).isDirectory() ? walk(f) : [f]; });

if (!existsSync(path.join(root, 'server.js')) && !existsSync(path.join(root, 'src')) && !existsSync(path.join(root, 'public'))) {
  const msg = 'Không thấy server.js, src hay public trong "' + root + '". Hãy đặt tệp cap-nhat.mjs vào thư mục ai-company (cùng chỗ với server.js) rồi chạy lại.';
  if (asJson) console.log(JSON.stringify({ loi: msg })); else console.error('\n⚠ ' + msg + '\n');
  process.exit(2);
}

function scan() {
  const st = { dung: [], khac: [], thieu: [], la: [] };
  for (const [rel] of expected) {
    const f = safe(rel);
    if (!existsSync(f)) { st.thieu.push({ rel }); continue; }
    const cur = readFileSync(f), h = sha(cur);
    if (h === expSha.get(rel)) st.dung.push({ rel }); else st.khac.push({ rel, giong: byHash.get(h) || null, byte: cur.length });
  }
  for (const top of ['src', 'public']) if (existsSync(path.join(root, top))) for (const f of walk(path.join(root, top))) {
    const rel = path.relative(root, f).split(path.sep).join('/');
    if (!expected.has(rel) && !/(^|\/)(\.DS_Store|Thumbs\.db)$/.test(rel)) st.la.push({ rel });
  }
  return st;
}

say('\nCẬP NHẬT CÔNG TY AI (mã bản ' + MA_BAN + ', ' + expected.size + ' tệp)');
say('Thư mục dự án: ' + root + '\n');
const before = scan();
say('  ✓ Đã đúng: ' + before.dung.length + ' tệp');
for (const x of before.khac) say('  ↻ Sai/cũ : ' + x.rel + (x.giong ? '   <- nội dung đang giống tệp ' + x.giong + ' (bị chép nhầm tệp)' : ''));
for (const x of before.thieu) say('  + Thiếu  : ' + x.rel);
for (const x of before.la) say('  ? Tệp lạ  : ' + x.rel + '   (không có trong bản chuẩn; chỉ nhắc, không xoá)');

const todo = [...before.khac, ...before.thieu];
let backup = null;
if (!todo.length) say('\nMọi tệp đã đúng, không cần cập nhật.');
else if (onlyCheck) say('\nChế độ chỉ kiểm tra: chưa sửa gì. Chạy lại không kèm --chi-kiem-tra để cập nhật.');
else {
  const d = new Date(), p2 = n => String(n).padStart(2, '0');
  backup = 'sao-luu-' + d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) + '-' + p2(d.getHours()) + p2(d.getMinutes()) + p2(d.getSeconds());
  for (const x of todo) {
    const f = safe(x.rel);
    if (existsSync(f)) { const b = path.join(safe(backup), x.rel); mkdirSync(path.dirname(b), { recursive: true }); copyFileSync(f, b); }
    mkdirSync(path.dirname(f), { recursive: true });
    writeFileSync(f, expected.get(x.rel));
  }
  say('\nĐã cập nhật ' + todo.length + ' tệp' + (before.khac.length ? ' (bản cũ được sao lưu trong thư mục ' + backup + ')' : '') + '.');
}

const after = scan();
const ok = !after.khac.length && !after.thieu.length;
if (asJson) console.log(JSON.stringify({ goc: root, maBan: MA_BAN, ok, truoc: { dung: before.dung.length, khac: before.khac, thieu: before.thieu, la: before.la }, sau: { dung: after.dung.length, khac: after.khac, thieu: after.thieu, la: after.la }, saoLuu: backup }));
else if (ok && todo.length && !onlyCheck) console.log('\n✅ XONG. Bây giờ: tắt cửa sổ start.bat (nếu đang mở), mở lại start.bat, rồi nhấn Ctrl + F5 trên trình duyệt.\n');
else if (!ok && !onlyCheck) console.log('\n⚠ Vẫn còn tệp chưa đúng sau khi cập nhật (có thể do quyền ghi tệp hoặc OneDrive đang đồng bộ). Hãy chụp màn hình này gửi cho tôi.\n');
process.exit(onlyCheck ? 0 : (ok ? 0 : 1));
